create or replace function public.claim_first_workspace_admin(p_workspace_id uuid) returns uuid language plpgsql security invoker set search_path=public as $$ begin return private.claim_first_workspace_admin(p_workspace_id); end; $$;
create or replace function public.delete_condominium(p_workspace_id uuid,p_legacy_id bigint,p_security_code text) returns void language plpgsql security invoker set search_path=public as $$ begin perform private.delete_condominium(p_workspace_id,p_legacy_id,p_security_code); end; $$;
create or replace function public.save_condominium(p_workspace_id uuid,p_legacy_id bigint,p_name text,p_address text,p_city text,p_postal_code text,p_province text,p_data jsonb) returns uuid language plpgsql security invoker set search_path=public as $$ begin return private.save_condominium(p_workspace_id,p_legacy_id,p_name,p_address,p_city,p_postal_code,p_province,p_data); end; $$;
create or replace function public.set_personal_security_code(p_code text,p_enabled boolean) returns void language plpgsql security invoker set search_path=public as $$ begin perform private.set_personal_security_code(p_code,p_enabled); end; $$;
create or replace function public.verify_personal_security_code(p_code text) returns boolean language plpgsql security invoker set search_path=public as $$ begin return private.verify_personal_security_code(p_code); end; $$;
